    #[test]
    fn present_original_download_hook_checks_path_and_original_evidence() {
        let _guard = env_lock();
        let previous_id = env::var_os("radarr_movie_id");
        let previous_file_id = env::var_os("radarr_moviefile_movie_id");
        env::set_var("radarr_movie_id", "7");
        env::remove_var("radarr_moviefile_movie_id");
        let temp = tempfile::tempdir().unwrap();
        let old = temp.path().join("old.mkv");
        let other = temp.path().join("other.mkv");
        std::fs::write(&old, b"old").unwrap();
        std::fs::write(&other, b"other").unwrap();
        stub_probe(old.to_str().unwrap(), &["eng"], &[]);
        let mut server = mockito::Server::new();
        let _movie = server
            .mock("GET", "/api/v3/movie/7")
            .with_body(
                json!({"id":7,"movieFileId":3,"originalLanguage":{"id":1,"name":"English"}})
                    .to_string(),
            )
            .create();
        let _file = server
            .mock("GET", "/api/v3/moviefile/3")
            .with_body(json!({"id":3,"path":old}).to_string())
            .create();
        let search = server
            .mock("GET", "/api/v3/release")
            .match_query(Matcher::Any)
            .with_body(
                json!([{"title":"Dual Audio", "languages":[{"name":"Spanish"}]}]).to_string(),
            )
            .expect(1)
            .create();
        let settings = ApiSettings {
            url: Some(server.url()),
            api_key: Some("test-key".into()),
            recovery_root: None,
        };
        let base = LanguageRequirements {
            enabled: true,
            audio: vec!["spa".into()],
            subtitles: vec![],
        };
        let options = RedownloadOptions {
            dry_run: true,
            candidate_policy: ServarrLanguageCandidatePolicy::CustomFormatOrTitle,
        };
        assert!(trigger_verified_redownload_with_present_original(
            IntegrationKind::Radarr,
            &settings,
            &base,
            options,
            None,
            true,
            &[other]
        )
        .is_err());
        let result = trigger_verified_redownload_with_present_original(
            IntegrationKind::Radarr,
            &settings,
            &base,
            options,
            None,
            true,
            &[old],
        )
        .unwrap();
        assert!(matches!(
            result,
            RedownloadOutcome::NoVerifiedRelease { .. }
        ));
        search.assert();
        match previous_id {
            Some(value) => env::set_var("radarr_movie_id", value),
            None => env::remove_var("radarr_movie_id"),
        }
        match previous_file_id {
            Some(value) => env::set_var("radarr_moviefile_movie_id", value),
            None => env::remove_var("radarr_moviefile_movie_id"),
        }
    }

    #[test]
    fn present_english_original_requires_explicit_release_language() {
        let mut client = test_client(IntegrationKind::Radarr, "http://127.0.0.1:1".into());
        client.keep_present_original_audio = true;
        let hint = json!({"title": "Dual Audio", "languages": [{"name": "Spanish"}]});
        let explicit =
            json!({"title": "Dual Audio", "languages": [{"name": "Spanish"}, {"name": "English"}]});
        assert!(!client.present_original_evidenced(&hint, Some("eng")));
        assert!(client.present_original_evidenced(&explicit, Some("eng")));
        assert!(client.present_original_evidenced(&hint, None));
        client.preserve_original_audio = true;
        assert!(client.present_original_evidenced(&hint, Some("eng")));
        client.preserve_original_audio = false;
        client.keep_present_original_audio = false;
        assert!(client.present_original_evidenced(&hint, Some("eng")));
    }

    #[test]
    fn original_audio_extra_non_english_requirements_are_explicit() {
        let requirements = LanguageRequirements {
            enabled: true,
            audio: vec!["eng".into(), "jpn".into(), "spa".into()],
            subtitles: vec![],
        };
        let target = Target::RadarrMovie { movie_id: 7 };
        let weak = json!({"title":"Dual Audio", "languages":[{"name":"Japanese"}], "customFormats":[{"name":"Multi Audio"}]});
        let enough = json!({"title":"Dual Audio", "languages":[{"name":"Japanese"},{"name":"Spanish"}], "customFormats":[{"name":"Multi Audio"}]});
        let no_english_hint =
            json!({"title":"Japanese", "languages":[{"name":"Japanese"},{"name":"Spanish"}]});
        for policy in [
            ServarrLanguageCandidatePolicy::CustomFormat,
            ServarrLanguageCandidatePolicy::CustomFormatOrTitle,
            ServarrLanguageCandidatePolicy::TitleGuess,
        ] {
            assert!(verified_release_candidates(
                std::slice::from_ref(&weak),
                target,
                &requirements,
                policy,
                false,
                Some("jpn")
            )
            .is_empty());
            assert_eq!(
                verified_release_candidates(
                    std::slice::from_ref(&weak),
                    target,
                    &requirements,
                    policy,
                    false,
                    None
                )
                .len(),
                1
            );
            assert_eq!(
                verified_release_candidates(
                    std::slice::from_ref(&enough),
                    target,
                    &requirements,
                    policy,
                    false,
                    Some("jpn")
                )
                .len(),
                1
            );
            assert!(verified_release_candidates(
                std::slice::from_ref(&no_english_hint),
                target,
                &requirements,
                policy,
                false,
                Some("jpn")
            )
            .is_empty());
        }
        assert!(verified_release_candidates(
            std::slice::from_ref(&enough),
            target,
            &requirements,
            ServarrLanguageCandidatePolicy::Strict,
            false,
            Some("jpn")
        )
        .is_empty());
        let english_original = LanguageRequirements {
            enabled: true,
            audio: vec!["eng".into(), "spa".into()],
            subtitles: vec![],
        };
        let english_only = json!({"title":"Dual Audio", "languages":[{"name":"English"}]});
        assert!(verified_release_candidates(
            std::slice::from_ref(&english_only),
            target,
            &english_original,
            ServarrLanguageCandidatePolicy::CustomFormatOrTitle,
            false,
            Some("eng")
        )
        .is_empty());
    }

    #[test]
    fn original_audio_candidate_requires_original_metadata_not_title() {
        let requirements = LanguageRequirements {
            enabled: true,
            audio: vec!["eng".into(), "jpn".into()],
            subtitles: vec!["eng".into()],
        };
        let target = Target::RadarrMovie { movie_id: 7 };
        let title_only = json!({"title":"Dual Audio Multi Subs", "languages":[{"name":"English"},{"name":"Unknown"}]});
        let original_only =
            json!({"title":"Dual Audio Multi Subs", "languages":[{"name":"Japanese"}]});
        let explicit_both = json!({"title":"Dual Audio Multi Subs", "languages":[{"name":"Japanese"},{"name":"English"}]});
        for policy in [
            ServarrLanguageCandidatePolicy::CustomFormat,
            ServarrLanguageCandidatePolicy::CustomFormatOrTitle,
            ServarrLanguageCandidatePolicy::TitleGuess,
        ] {
            let mut title_hint = title_only.clone();
            title_hint["customFormats"] = json!([{"name":"Multi Audio"}, {"name":"Multi Sub"}]);
            assert_eq!(
                verified_release_candidates(
                    std::slice::from_ref(&title_hint),
                    target,
                    &requirements,
                    policy,
                    false,
                    Some("jpn")
                )
                .len(),
                0
            );
            assert_eq!(
                verified_release_candidates(
                    std::slice::from_ref(&title_hint),
                    target,
                    &requirements,
                    policy,
                    false,
                    None
                )
                .len(),
                1
            );
            let mut explicit = original_only.clone();
            explicit["customFormats"] = json!([{"name":"Multi Audio"}, {"name":"Multi Sub"}]);
            assert_eq!(
                verified_release_candidates(
                    std::slice::from_ref(&explicit),
                    target,
                    &requirements,
                    policy,
                    false,
                    Some("jpn")
                )
                .len(),
                1
            );
        }
        let strict = json!({"title":"release", "languages":[{"name":"Japanese"},{"name":"English"}], "subtitleLanguages":["eng"]});
        assert_eq!(
            verified_release_candidates(
                std::slice::from_ref(&strict),
                target,
                &requirements,
                ServarrLanguageCandidatePolicy::Strict,
                false,
                Some("jpn")
            )
            .len(),
            1
        );
        assert_eq!(
            verified_release_candidates(
                std::slice::from_ref(&explicit_both),
                target,
                &requirements,
                ServarrLanguageCandidatePolicy::Strict,
                false,
                Some("jpn")
            )
            .len(),
            0
        );
        let missing_subtitles =
            json!({"title":"Dual Audio", "languages":[{"name":"Japanese"},{"name":"English"}]});
        assert_eq!(
            verified_release_candidates(
                std::slice::from_ref(&missing_subtitles),
                target,
                &requirements,
                ServarrLanguageCandidatePolicy::CustomFormatOrTitle,
                false,
                Some("jpn")
            )
            .len(),
            0
        );
    }

