    #[test]
    fn sonarr_bad_queue_reason_detects_invalid_episode_and_mismatch() {
        let invalid = json!({
            "status": "completed",
            "trackedDownloadStatus": "warning",
            "statusMessages": [{
                "title": "bad file.mp4",
                "messages": ["Invalid season or episode"]
            }]
        });
        assert_eq!(
            sonarr_bad_queue_reason(&invalid, 0),
            Some("invalid season or episode")
        );

        let mismatch = json!({
            "status": "completed",
            "trackedDownloadStatus": "warning",
            "statusMessages": [{
                "title": "One or more episodes expected in this release were not imported or missing from the release",
                "messages": ["Episode 2x05 was not found in the grabbed release"]
            }]
        });
        assert_eq!(
            sonarr_bad_queue_reason(&mismatch, 0),
            Some("episode mismatch or multi-episode pack")
        );

        let quality = json!({
            "status": "completed",
            "trackedDownloadStatus": "warning",
            "statusMessages": [{
                "title": "candidate.mkv",
                "messages": ["Not an upgrade for existing episode file(s). Existing quality: Bluray-1080p. New Quality Bluray-720p."]
            }]
        });
        assert_eq!(sonarr_bad_queue_reason(&quality, 0), None);

        let stale = json!({
            "status": "queued",
            "trackedDownloadStatus": "ok",
            "trackedDownloadState": "downloading",
            "protocol": "torrent",
            "size": 0,
            "sizeleft": 0,
            "added": "2000-01-01T00:00:00Z"
        });
        assert_eq!(
            sonarr_bad_queue_reason(&stale, 2),
            Some("stale zero-size torrent queue item")
        );
        assert_eq!(sonarr_bad_queue_reason(&stale, 0), None);
    }

    #[test]
    fn sonarr_queue_health_summary_counts_remediation_states() {
        let records = vec![
            json!({
                "status": "completed",
                "trackedDownloadState": "importPending",
                "trackedDownloadStatus": "ok"
            }),
            json!({
                "status": "completed",
                "trackedDownloadState": "importBlocked",
                "trackedDownloadStatus": "warning",
                "statusMessages": [{"messages": ["Found matching series via grab history"]}]
            }),
            json!({
                "status": "completed",
                "trackedDownloadStatus": "warning",
                "statusMessages": [{"messages": ["Wrong episode"]}]
            }),
            json!({
                "id": 1,
                "status": "queued",
                "trackedDownloadState": "downloading",
                "trackedDownloadStatus": "ok",
                "protocol": "torrent",
                "size": 0,
                "sizeleft": 0,
                "added": "2000-01-01T00:00:00Z"
            }),
            json!({
                "id": 2,
                "status": "queued",
                "trackedDownloadState": "downloading",
                "trackedDownloadStatus": "ok",
                "protocol": "torrent",
                "size": 1024,
                "sizeleft": 512
            }),
            json!({
                "id": 3,
                "status": "downloading",
                "trackedDownloadState": "downloading",
                "trackedDownloadStatus": "ok",
                "protocol": "torrent",
                "size": 0,
                "sizeleft": 0
            }),
            json!({
                "id": 4,
                "status": "downloading",
                "trackedDownloadState": "downloading",
                "trackedDownloadStatus": "ok",
                "protocol": "torrent",
                "size": 2048,
                "sizeleft": 1024
            }),
        ];

        let summary = sonarr_queue_health_summary(&records, 2);
        assert_eq!(
            summary,
            QueueHealthSummary {
                total: 7,
                completed_import_pending: 1,
                completed_import_blocked: 1,
                completed_warning: 2,
                stale_zero_size_torrents: 1,
                queued_zero_size_torrents: 1,
                queued_nonzero_torrents: 1,
                downloading_zero_size_torrents: 1,
                downloading_nonzero_torrents: 1,
                invalid_or_mismatch_warnings: 1,
            }
        );
    }

